    private static readonly object CapabilityGate=new();
    private static readonly Dictionary<string,string> AfirCapabilities=new();
    public static void ClearCache(){lock(CapabilityGate)AfirCapabilities.Clear();}
    private static GDScript Effects()=>GD.Load<GDScript>("res://Workspaces/AudioWorkspace/audio_effects.gd");
    private static CSharpScript Impulse()=>GD.Load<CSharpScript>("res://Workspaces/AudioWorkspace/KiwiAudioImpulse.cs");
    private static CSharpScript Doppler()=>GD.Load<CSharpScript>("res://Workspaces/AudioWorkspace/KiwiAudioDoppler.cs");
    private static string Encoder()=>GD.Load<CSharpScript>("res://scripts/actors/core/ActorVideo.cs").Call("executable","ffmpeg").AsString();
    private static double Tail(GArray effects)=>Effects().Call("tail_seconds",effects).AsDouble();
    private static int InputCount(GArray inputs){int count=0;foreach(var value in inputs)if(value.AsString()=="-i")count++;return count;}
    private static void Append(GArray target,params string[] values){foreach(string value in values)target.Add(value);}
    public string afir_normalization(RefCounted? job){string encoder=Encoder();lock(CapabilityGate)if(AfirCapabilities.TryGetValue(encoder,out var cached))return cached;using var process=new AudioEncoderProcessOperations();var probe=process.run(encoder,new[]{"-hide_banner","-h","filter=afir"},1,job,15);string output=Text(probe,"stdout")+"\n"+Text(probe,"diagnostics"),result=output.Contains("irnorm",StringComparison.Ordinal)?"irnorm=-1":"gtype=none";if(Bool(probe,"success"))lock(CapabilityGate)AfirCapabilities[encoder]=result;return result;}
    public Settings effect_chain(GArray effects,int rate,string context,string directory,GArray inputs,RefCounted? job)
    {
        var filters=new List<string>();using var cache=new AudioSourceCacheOperations();for(int index=0;index<effects.Count;index++){var effect=effects[index].AsGodotDictionary();if(!Bool(effect,"enabled",true))continue;string type=Text(effect,"type");var parameters=Dict(effect,"parameters");if(type=="doppler")return new Settings {["error"]="Doppler must use the ordered float32 staging path."};if(type is not "convolution" and not "plate" and not "spring" and not "pingpong"){string rendered=Effects().Call("rendered_filter",effect,rate,context+index).AsString();if(rendered.Length>0)filters.Add(rendered);continue;}double wet=Math.Clamp(Number(parameters,"mix",.3),0,1);if(wet<=0)continue;AudioStreamWav? impulse;if(type=="convolution"){var source=GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("source",Get(parameters,"impulse"),Variant.From(job)).As<AudioStream>();if(source==null)return new Settings {["error"]="Choose an impulse-response audio file for Convolution Reverb."};var decoded=cache.decode(source,rate,0,Impulse().Call("duration",type,parameters).AsDouble(),20);if(Text(decoded,"error").Length>0)return decoded;var samples=decoded["samples"].AsVector2Array();if(samples.Length==0)return new Settings {["error"]="The impulse response is empty."};impulse=cache.to_wav(samples,rate,true);}else impulse=Impulse().Call("generate",type,parameters,rate,Variant.From(job)).As<AudioStreamWav>();if(impulse==null)return new Settings {["error"]="Impulse generation was cancelled or failed."};using(impulse){string tag="ir_"+(context+index).Sha256Text()[..12],path=directory.PathJoin(tag+".wav");if(impulse.SaveToWav(path)!=Error.Ok)return new Settings {["error"]="Could not stage the convolution impulse."};int inputIndex=InputCount(inputs);Append(inputs,"-i",path);string pre=type=="pingpong"?"pan=stereo|c0=0.5*c0+0.5*c1|c1=0.5*c0+0.5*c1,":"";string filter=$"asplit=2[{tag}d][{tag}w];[{tag}w]{pre}apad=pad_dur={Format(impulse.GetLength())}[{tag}p];[{inputIndex}:a]aresample={rate},aformat=channel_layouts=stereo[{tag}i];[{tag}p][{tag}i]afir=dry=1:wet=1:{afir_normalization(job)}:irgain=1:maxir=20:minp=256:maxp=2048[{tag}c];[{tag}d][{tag}c]amix=inputs=2:normalize=0:weights='1 {Format(wet)}'";if(Cancelled(job))return new Settings {["error"]="Cancelled."};filters.Add(filter);}}return new Settings {["error"]="",["filter"]=string.Join(',',filters)};
    }
    public long staging_bytes(string directory){long total=0;using var access=DirAccess.Open(directory);if(access==null)return 0;foreach(string name in access.GetFiles()){using var file=Godot.FileAccess.Open(directory.PathJoin(name),Godot.FileAccess.ModeFlags.Read);if(file!=null)total+=(long)file.GetLength();}return total;}
    public string stage_graph(string[] filters,string selectedLabel){string graph=string.Join(";\n",filters);var references=new Dictionary<string,int>();foreach(Match match in Regex.Matches(graph,@"\[([A-Za-z_][A-Za-z0-9_]*)\]")){string label=match.Groups[1].Value;references[label]=references.TryGetValue(label,out int count)?count+1:1;}foreach(var pair in references)if(pair.Value==1&&pair.Key!=selectedLabel)graph+=";\n["+pair.Key+"]anullsink";return graph;}
    public Settings render_float_stage(GArray inputs,string[] filters,string label,string path,int rate,long frames,long maxBytes,RefCounted? job)
    {
        if(Cancelled(job))return Failure("Cancelled.");string encoder=Encoder();if(encoder.Length==0)return Failure("FFmpeg is required for offline Doppler.");string graph=stage_graph(filters,label),graphPath=path+".ffgraph";using(var file=Godot.FileAccess.Open(graphPath,Godot.FileAccess.ModeFlags.Write)){if(file==null)return Failure("Could not create the Doppler staging graph.");file.StoreString(graph);maxBytes=Math.Max(0,maxBytes-(long)file.GetPosition());}if(maxBytes<8)return Failure("No room remains in the Doppler staging budget. Split or bake a shorter region.");var args=new List<string> {"-hide_banner","-v","error","-n","-threads","1","-filter_complex_threads","1"};foreach(var value in inputs)args.Add(value.AsString());args.AddRange(new[]{"-filter_complex_script",graphPath,"-map","["+label+"]","-ar",rate.ToString(),"-ac","2","-c:a","pcm_f32le","-f","f32le","-fs",maxBytes.ToString(),"-progress","pipe:1",path});var result=execute(encoder,args.ToArray(),(double)frames/rate,job);if(!Bool(result,"success"))return result;using var output=Godot.FileAccess.Open(path,Godot.FileAccess.ModeFlags.Read);if(output==null)return Failure("Doppler staging produced no readable audio.");long bytes=(long)output.GetLength();if(bytes<=0||bytes%8!=0||bytes>=maxBytes)return Failure("Doppler staging reached its byte limit or produced incomplete float32 audio. Split or bake a shorter region; no partial stage was used.");result["stage_frames"]=bytes/8;return result;
    }
    public Settings ordered_effect_chain(GArray effects,int rate,string context,string directory,GArray inputs,string[] filterValues,string inputLabel,string[] chainValues,double duration,RefCounted? job)
    {
        var pending=new GArray();var filters=new List<string>(filterValues);var chain=new List<string>(chainValues);double currentDuration=Math.Max(1.0/rate,duration);int part=0;for(int index=0;index<effects.Count;index++){var effect=effects[index].AsGodotDictionary();if(!Bool(effect,"enabled",true))continue;string type=Text(effect,"type");if(type is not "doppler" and not "dereverb"){pending.Add(effect);continue;}bool restoration=type=="dereverb";var parameters=restoration?Dict(effect,"parameters"):Doppler().Call("parameters",Dict(effect,"parameters")).AsGodotDictionary();if(Number(parameters,restoration?"strength":"mix",restoration ? .6 : 0)<=0)continue;var prepared=effect_chain(pending,rate,context+"_part"+part,directory,inputs,job);if(Text(prepared,"error").Length>0)return prepared;string filter=Text(prepared,"filter");if(filter.Length>0)chain.Add(filter);currentDuration+=Tail(pending);pending.Clear();double tail=restoration?0:Doppler().Call("tail_seconds",parameters).AsDouble();long inputFrames=(long)Math.Ceiling(currentDuration*rate),tailFrames=(long)Math.Ceiling(tail*rate),outputFrames=inputFrames+tailFrames,stageBytes=restoration?64L*1024*1024:512L*1024*1024;if(outputFrames*8>stageBytes)return new Settings {["error"]="Doppler staging is limited to 512 MiB per stereo float stage. Split or bake a shorter region."};const long jobBytes=2L*1024*1024*1024;if(staging_bytes(directory)+(inputFrames+outputFrames)*8>jobBytes)return new Settings {["error"]="Doppler intermediates exceed the 2 GiB job staging limit. Split or bake a shorter region."};string tag="doppler_"+(context+"_"+index).Sha256Text()[..16];if(chain.Count==0)chain.Add("anull");filters.Add("["+inputLabel+"]"+string.Join(',',chain)+"["+tag+"]");string rawPath=directory.PathJoin(tag+"_input.f32"),wetPath=directory.PathJoin(tag+"_output.f32");long tailBytes=tailFrames*8,inputBudget=Math.Min(stageBytes-tailBytes,Math.Max(0,(jobBytes-staging_bytes(directory)-tailBytes)/2));var rendered=render_float_stage(inputs,filters.ToArray(),tag,rawPath,rate,inputFrames,inputBudget,job);if(!Bool(rendered,"success"))return rendered;long actualFrames=rendered["stage_frames"].AsInt64();if(staging_bytes(directory)+(actualFrames+tailFrames)*8>jobBytes)return new Settings {["error"]="Doppler intermediates exceed the 2 GiB job staging limit. Split or bake a shorter region."};Script processor=restoration?GD.Load<GDScript>("res://Workspaces/AudioWorkspace/audio_restoration.gd"):Doppler();var processed=processor.Call("process_f32",rawPath,wetPath,effect,rate,Variant.From(job)).AsGodotDictionary();if(!Bool(processed,"success"))return processed;DirAccess.RemoveAbsolute(rawPath);filters.Add("["+tag+"]anullsink");int nextInput=InputCount(inputs);Append(inputs,"-f","f32le","-ar",rate.ToString(),"-ac","2","-i",wetPath);inputLabel=nextInput+":a";chain.Clear();currentDuration=Number(processed,"duration");part++;}var final=effect_chain(pending,rate,context+"_part"+part,directory,inputs,job);if(Text(final,"error").Length>0)return final;string last=Text(final,"filter");if(last.Length>0)chain.Add(last);return new Settings {["error"]="",["filters"]=filters.ToArray(),["input_label"]=inputLabel,["chain"]=chain.ToArray()};
    }
